const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);

const pad = (n) => String(n).padStart(2, '0');
const fechaYYYYMMDD = `${yesterday.getFullYear()}-${pad(yesterday.getMonth()+1)}-${pad(yesterday.getDate())}`;

return [{
  json: {
    fechaInicio: fechaYYYYMMDD,   // ej: "2026-04-14"
    fechaFin: fechaYYYYMMDD,      // mismo día (el endpoint añade +1 día internamente)
    fechaLegible: yesterday.toLocaleDateString('es-ES', {
      weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
    })
  }
}];

const response = $input.first().json;

// Usa el nombre EXACTO de tu nodo de fechas
const fechaLegible = $('calculo de fechas').first().json.fechaLegible;

// La API devuelve { status, total, incidencias: [...] }
const incidencias = response.incidencias || [];

return [{
  json: {
    incidencias,
    total: response.total || incidencias.length,
    fechaLegible
  }
}];

const resumenTexto = $input.first().json.output || 'No se pudo generar el resumen.';

const incidencias = $('consolidar datos').first().json.incidencias;
const fechaLegible = $('calculo de fechas').first().json.fechaLegible;
const total = $('consolidar datos').first().json.total;

return [{
  json: {
    resumenTexto,
    incidencias,
    fechaLegible,
    total
  }
}];
